// UK Projection constants (centered on Great Britain & Ireland)
export const UK_PROJECTION = {
  minLng: -10.5,
  maxLng: 2.2,
  minLat: 49.8,
  maxLat: 59.2,
  cos54: 0.587785,
  scale: 88.0 / 9.4,
  yOffset: 94.0,
  xOffset: (100.0 - 12.7 * 0.587785 * (88.0 / 9.4)) / 2.0,
};

export function projectUkCoords(lng, lat) {
  const x =
    UK_PROJECTION.xOffset +
    (lng - UK_PROJECTION.minLng) * UK_PROJECTION.cos54 * UK_PROJECTION.scale;
  const y = UK_PROJECTION.yOffset - (lat - UK_PROJECTION.minLat) * UK_PROJECTION.scale;
  return { x, y };
}

// World Projection constants (Transatlantic view: North America + Europe)
export const WORLD_PROJECTION = {
  minLng: -130.0,
  maxLng: 20.0,
  minLat: 20.0,
  maxLat: 65.0,
  lngSpan: 150.0,
  latSpan: 45.0,
};

export function projectWorldCoords(lng, lat) {
  const x = ((lng - WORLD_PROJECTION.minLng) / WORLD_PROJECTION.lngSpan) * 94.0 + 3.0;
  const y = (1.0 - (lat - WORLD_PROJECTION.minLat) / WORLD_PROJECTION.latSpan) * 90.0 + 5.0;
  return { x, y };
}
